/**
 * @param {string[]} classroom
 * @param {number} energy
 * @return {number}
 */
var minMoves = function(classroom, energy) {
    const matrix = classroom.map(x => x.split(''));
    const m = matrix.length;
    const n = matrix[0].length;

    let start = null;
    let totalLitter = 0;

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            if (matrix[row][col] === 'S') {
                start = [row, col];
            } else if (matrix[row][col] === 'L') {
                totalLitter++;
            }
        }
    }

    if (!start) return -1;

    const memo = new Map();
    let stack = [[...start, energy, totalLitter, new Set(), '']];
    let steps = 0;

    while (stack.length > 0) {
        let next = [];

        for (let [row, col, energyLeft, litterLeft, litterSeen, signature] of stack) {
            if (row < 0 || row >= m || col < 0 || col >= n) continue;
            if (matrix[row][col] === 'X') continue;

            const key = row + ':' + col + ':' + energyLeft + ':' + signature;
            if (memo.has(key) && memo.get(key) <= litterLeft) continue;

            memo.set(key, litterLeft);

            if (matrix[row][col] === 'R') {
                energyLeft = energy;
            } else if (matrix[row][col] === 'L' && !litterSeen.has(row + ':' + col)) {
                litterLeft--;

                if (litterLeft === 0) return steps;

                litterSeen.add(row + ':' + col);
                signature += '|' + row + ':' + col;
            }

            if (energyLeft === 0) continue;
            energyLeft--;

            next.push(
                [row, col + 1, energyLeft, litterLeft, new Set(litterSeen), signature],
                [row + 1, col, energyLeft, litterLeft, new Set(litterSeen), signature],
                [row, col - 1, energyLeft, litterLeft, new Set(litterSeen), signature],
                [row - 1, col, energyLeft, litterLeft, new Set(litterSeen), signature],
            );
        }

        stack = next;
        steps++;
    }

    return -1;
};

